import { processResourceRecord, toFullName } from "../utilities.mjs";
import assert from 'node:assert';

/**
 * Testing file generated by Claude Opus 5.5 [High]
 * Run with: node test.mjs
 */

/**
 * Defaults used by every test unless the test overrides them
 */
const DEFAULTS = {
    previousName: 'api',
    previousTtl: 300,
    origin: 'example.com.',
    defaultTtl: '60',
};

/**
 * Builds the array processResourceRecord should return:
 * [record, previousName, previousTtl]
 */
function expected(record, previousName, previousTtl) {
    return [
        {
            name: record.name,
            ttl: record.ttl,
            class: record.class ?? 'IN',
            type: record.type,
            data: record.data,
            priority: record.priority, // undefined for non-MX records
        },
        previousName,
        previousTtl,
    ];
}

const tests = [
    // ---------- Valid A records ----------
    {
        label: 'Basic A record, TTL from $TTL',
        line: ['@', 'IN', 'A', '192.0.2.1'],
        want: expected({ name: '@', ttl: 60, type: 'A', data: '192.0.2.1' }, '@', 60),
    },
    {
        label: 'Line has its own TTL',
        line: ['www', '300', 'IN', 'A', '192.0.2.3'],
        want: expected({ name: 'www', ttl: 300, type: 'A', data: '192.0.2.3' }, 'www', 300),
    },
    {
        label: 'Class and TTL swapped (IN 300)',
        line: ['ftp', 'IN', '300', 'A', '192.0.2.4'],
        want: expected({ name: 'ftp', ttl: 300, type: 'A', data: '192.0.2.4' }, 'ftp', 300),
    },
    {
        label: 'No class, defaults to IN',
        line: ['api', '300', 'A', '192.0.2.5'],
        want: expected({ name: 'api', ttl: 300, type: 'A', data: '192.0.2.5' }, 'api', 300),
    },
    {
        label: 'No name, copied from previousName',
        line: ['IN', 'A', '192.0.2.6'],
        want: expected({ name: 'api', ttl: 60, type: 'A', data: '192.0.2.6' }, 'api', 60),
    },
    {
        label: 'No name and no previousName, falls back to origin',
        line: ['IN', 'A', '192.0.2.6'],
        args: { previousName: undefined },
        want: expected(
            { name: 'example.com.', ttl: 60, type: 'A', data: '192.0.2.6' },
            'example.com.',
            60
        ),
    },
    {
        label: 'TTL of 0 is kept (the 0 trap)',
        line: ['@', '0', 'IN', 'A', '192.0.2.8'],
        want: expected({ name: '@', ttl: 0, type: 'A', data: '192.0.2.8' }, '@', 0),
    },
    {
        label: 'Name starting with a digit is not a TTL',
        line: ['2fa', '300', 'IN', 'A', '192.0.2.7'],
        want: expected({ name: '2fa', ttl: 300, type: 'A', data: '192.0.2.7' }, '2fa', 300),
    },
    {
        label: 'No $TTL, falls back to previousTtl',
        line: ['IN', 'A', '192.0.2.6'],
        args: { defaultTtl: undefined },
        want: expected({ name: 'api', ttl: 300, type: 'A', data: '192.0.2.6' }, 'api', 300),
    },

    // ---------- Other types ----------
    {
        label: 'CNAME pointing to a host called "A" (tests the break)',
        line: ['www', 'IN', 'CNAME', 'A'],
        want: expected({ name: 'www', ttl: 60, type: 'CNAME', data: 'A' }, 'www', 60),
    },
    {
        label: 'Full MX line with 6 items',
        line: ['mail', '300', 'IN', 'MX', '10', 'mail.example.com.'],
        want: expected(
            { name: 'mail', ttl: 300, type: 'MX', data: 'mail.example.com.', priority: 10 },
            'mail',
            300
        ),
    },
    {
        label: 'MX priority of 0 is kept',
        line: ['@', 'IN', 'MX', '0', 'mail.example.com.'],
        want: expected(
            { name: '@', ttl: 60, type: 'MX', data: 'mail.example.com.', priority: 0 },
            '@',
            60
        ),
    },

    // ---------- Lines that should be rejected (return null) ----------
    {
        label: 'Unsupported type (TXT)',
        line: ['www', 'IN', 'TXT', 'hello'],
        want: null,
    },
    {
        label: 'No data after the type',
        line: ['www', 'IN', 'A'],
        want: null,
    },
    {
        label: 'Too much data for an A record',
        line: ['www', 'IN', 'A', '1.1.1.1', '2.2.2.2'],
        want: null,
    },
    {
        label: 'MX with no priority',
        line: ['@', 'IN', 'MX', 'mail.example.com.'],
        want: null,
    },
    {
        label: 'MX priority is not a number',
        line: ['@', 'IN', 'MX', 'ten', 'mail.example.com.'],
        want: null,
    },
    {
        label: 'Two TTLs on one line',
        line: ['www', '300', '600', 'A', '192.0.2.3'],
        want: null,
    },
    {
        label: 'Two names on one line',
        line: ['www', 'mail', 'A', '192.0.2.3'],
        want: null,
    },
    {
        label: 'More than 3 items before the type',
        line: ['www', 'mail', '300', 'IN', 'A', '192.0.2.3'],
        want: null,
    },
    {
        label: 'No TTL anywhere',
        line: ['IN', 'A', '192.0.2.6'],
        args: { defaultTtl: undefined, previousTtl: undefined },
        want: null,
    },
    {
        label: 'Broken $TTL value',
        line: ['www', 'IN', 'A', '192.0.2.3'],
        args: { defaultTtl: 'abc' },
        want: null,
    },
];

/**
 * toFullName tests
 * Each one checks that a zone file name becomes the full name
 * the server compares against queries: no trailing dot, lowercase
 */
const nameTests = [
    {
        label: '@ becomes the origin',
        name: '@',
        origin: 'example.com.',
        want: 'example.com',
    },
    {
        label: 'Short name gets the origin added',
        name: 'www',
        origin: 'example.com.',
        want: 'www.example.com',
    },
    {
        label: 'Name ending in a dot is already full',
        name: 'mail.other.com.',
        origin: 'example.com.',
        want: 'mail.other.com',
    },
    {
        label: 'Capitals in the name and origin are lowercased',
        name: 'WWW',
        origin: 'Example.COM.',
        want: 'www.example.com',
    },
    {
        label: 'Origin without a trailing dot',
        name: 'www',
        origin: 'example.com',
        want: 'www.example.com',
    },
    {
        label: 'Deeper short name',
        name: 'api.v2',
        origin: 'example.com.',
        want: 'api.v2.example.com',
    },
];

/**
 * Run every test and print PASS or FAIL
 */
let passed = 0;
let failed = 0;

console.log('--- processResourceRecord ---');
for (const test of tests) {
    const a = { ...DEFAULTS, ...test.args };
    const got = processResourceRecord(test.line, a.previousName, a.previousTtl, a.origin, a.defaultTtl);

    try {
        assert.deepStrictEqual(got, test.want);
        console.log(`PASS  ${test.label}`);
        passed++;
    } catch {
        console.log(`FAIL  ${test.label}`);
        console.log('      line:    ', test.line);
        console.log('      expected:', test.want);
        console.log('      got:     ', got);
        failed++;
    }
}

console.log('\n--- toFullName ---');
for (const test of nameTests) {
    const got = toFullName(test.name, test.origin);

    try {
        assert.strictEqual(got, test.want);
        console.log(`PASS  ${test.label}`);
        passed++;
    } catch {
        console.log(`FAIL  ${test.label}`);
        console.log(`      toFullName('${test.name}', '${test.origin}')`);
        console.log('      expected:', test.want);
        console.log('      got:     ', got);
        failed++;
    }
}

const total = tests.length + nameTests.length;
console.log(`\n${passed} passed, ${failed} failed, ${total} total`);
if (failed > 0) process.exitCode = 1;